/// `_wallet` recomputes the total from its chains rather than trusting a passed-in figure.
#[test]
fn builds_wallet_totals_from_chains() {
    let py = case("wallet");
    let chains: Vec<ChainBucket> = serde_json::from_value(py["chains"].clone()).unwrap();
    let wallet = Wallet::new("0x7Fce9c293dBD6d050455B986cb6850114Aad71a8", chains);

    assert_eq!(wallet.total, 2048.25, "1792.0 + 256.25");
    assert_same(
        "wallet",
        "total is the sum of the buckets",
        &py,
        &serde_json::to_value(&wallet).unwrap(),
    );

    // A chain that came back below dust is dropped by `_chain_result` before `_wallet` sums,
    // so the dropped value must not appear in the total.
    let dropped = case("wallet_drops_none_chains");
    assert_eq!(
        dropped["total"].as_f64().unwrap(),
        2048.25,
        "the sub-dust chain must not be counted"
    );
    assert_eq!(
        dropped["chains"].as_array().unwrap().len(),
        2,
        "and must not be listed"
    );
}

/// The top-level envelope: six keys, `rates` always an object, both sentiment legs present.
#[test]
fn builds_snapshot_envelope() {
    // The degraded path — everything timed out.
    let degraded = PortfolioSnapshot::new(
        Vec::new(),
        Vec::new(),
        fallback_rates(),
        PortfolioSentiment::default(),
        1783924800.0,
    );
    assert_same(
        "snapshot_degraded",
        "rates falls back to an object; sentiment legs are null but present",
        &case("snapshot_degraded"),
        &serde_json::to_value(&degraded).unwrap(),
    );

    // The populated path, rebuilt around the corpus's own wallets.
    let py = case("snapshot_full");
    let wallets: Vec<Wallet> = serde_json::from_value(py["wallets"].clone()).unwrap();
    let rainbow: Rainbow = serde_json::from_value(py["sentiment"]["btc_rainbow"].clone()).unwrap();
    let full = PortfolioSnapshot::new(
        vec!["0x7Fce9c293dBD6d050455B986cb6850114Aad71a8".into()],
        wallets,
        Rates {
            usd: 1.0,
            thb: Some(32.5),
            btc_usd: Some(65536.0),
        },
        PortfolioSentiment {
            fear_greed: Some(FearGreed {
                value: 42,
                classification: "Fear".into(),
            }),
            btc_rainbow: Some(rainbow),
        },
        1783924800.5,
    );
    assert_eq!(full.total, 3072.25, "2048.25 (wallet) + 1024.0 (KuCoin)");
    assert_same(
        "snapshot_full",
        "the populated envelope",
        &py,
        &serde_json::to_value(&full).unwrap(),
    );

    // `addresses` lists only the requested wallets — the appended KuCoin wallet is not one.
    assert_eq!(py["addresses"].as_array().unwrap().len(), 1);
    assert_eq!(py["wallets"].as_array().unwrap().len(), 2);
    assert_eq!(py["wallets"][1]["address"], "KuCoin");
}

/// The portfolio envelope's `sentiment` has exactly two keys.
///
/// `market::Sentiment` (the `/api/sentiment` shape) also carries `mvrv_zscore`, `sopr`,
/// `puell` and `fetched_at`. Reusing it here would put four keys into every portfolio
/// response that `build_portfolios` never emits, which is why `PortfolioSentiment` exists.
#[test]
fn portfolio_sentiment_has_exactly_two_keys() {
    let value = serde_json::to_value(PortfolioSentiment::default()).unwrap();
    let keys: BTreeSet<&str> = value
        .as_object()
        .unwrap()
        .keys()
        .map(String::as_str)
        .collect();
    assert_eq!(keys, BTreeSet::from(["fear_greed", "btc_rainbow"]));
    assert_eq!(value, json!({"fear_greed": null, "btc_rainbow": null}));
}

/// A price band whose tick maths overflows: `fin()` nulls the non-finite bounds, so the keys
/// stay present with null values and `full` reports the position as unbounded.
#[test]
fn price_band_nulls_non_finite_bounds() {
    let py = case("price_band_full_range");
    let parsed: Position = serde_json::from_value(py.clone()).unwrap();
    let band: &PriceBand = parsed.price_band.as_ref().expect("band must be present");

    assert!(band.full, "a ±887272-tick range is effectively full-range");
    assert_eq!(band.base, "WETH");
    assert_eq!(band.quote, "USDC");
    for (name, v) in [
        ("lower", band.lower),
        ("upper", band.upper),
        ("cur", band.cur),
    ] {
        assert!(
            v.is_none_or(f64::is_finite),
            "{name} must be null or finite — `fin()` never lets an inf through"
        );
    }
    assert_same(
        "price_band",
        &py.to_string(),
        &py,
        &serde_json::to_value(&parsed).unwrap(),
    );
}
